// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC4626} from "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {CompliantToken} from "./base/CompliantToken.sol";
import {IWithdrawPolicy} from "./interfaces/IWithdrawPolicy.sol";

/// @title RwaVaultV3 — fundo ERC-4626 custodial, com compliance uRWA plugável
/// @notice Cotas de um fundo cujo lastro é uma stablecoin (USDC/BRLA/…). Diferente de um
///         vault DeFi puro, o capital SAI do contrato para financiar ativo real, então
///         `totalAssets()` soma duas parcelas de naturezas diferentes: o saldo ocioso no
///         contrato (verificável por qualquer um) e o capital aplicado (número REPORTADO
///         pelo ORACLE). Essa segunda parcela é a premissa de confiança do produto e está
///         aqui explícita, não escondida.
///
/// @dev Três poderes separados de propósito, além dos herdados (ENFORCER/PAUSER):
///      - DEFAULT_ADMIN_ROLE concede papéis, pluga compliance e política. Não move dinheiro.
///      - MANAGER_ROLE saca e devolve capital. Neutro no preço da cota.
///      - ORACLE_ROLE reporta o valor do capital aplicado. É a ÚNICA operação que move o
///        preço, e por isso tem trava de validade e teto de variação.
///
///      A aritmética de cota virtual do OpenZeppelin, e o que move o preço, estão em
///      `contracts/INVARIANTS.md` — §2 e §4.
contract RwaVaultV3 is ERC4626, CompliantToken, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE"); // saque / devolução
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE"); // reporte de marcação

    /// @dev Cota é fungível de classe única, então o tokenId do compliance é sempre 0 —
    ///      a mesma convenção do CompliantERC20.
    uint256 private constant FUNGIBLE_ID = 0;

    /// @notice Capital fora do contrato, aplicado em ativo real. Reportado, não verificável.
    uint256 public deployedCapital;

    /// @notice Timestamp do último reporte de `deployedCapital`. 0 = nunca reportado.
    uint64 public reportedAt;

    /// @notice Idade máxima do reporte para depósito/resgate serem aceitos, em segundos.
    ///         Só vale quando há capital aplicado — sem capital fora, não há o que marcar.
    uint64 public maxReportAge;

    /// @notice Teto de variação de um reporte para o seguinte, em basis points (10000 = 100%).
    uint16 public maxReportDeviationBps;

    /// @notice Piso do PRIMEIRO depósito, nas menores unidades do lastro. Encarece o ataque
    ///         de doação/inflação, em que alguém entra com o mínimo e depois transfere direto
    ///         para o contrato para distorcer a razão cota/ativo dos próximos.
    uint256 public immutable minFirstDeposit;

    /// @notice Política de destino do saque. `address(0)` = sem restrição.
    IWithdrawPolicy public withdrawPolicy;

    /// @notice Metadado do fundo (ERC-7572): URL de um JSON, ou o JSON embutido.
    string private _contractURI;

    /// @dev Lastro que entrou no contrato pelos caminhos previstos — depósito e devolução de
    ///      capital — menos o que saiu por resgate e por saque. Comparado ao saldo real em
    ///      `unbookedAssets()`. Informativo: `totalAssets()` não o usa (ver item 8 acima).
    uint256 private _idleBooked;

    event CapitalWithdrawn(address indexed to, uint256 amount, uint256 deployedCapital);
    event CapitalReturned(address indexed from, uint256 amount, uint256 deployedCapital);
    event DeployedCapitalReported(uint256 previous, uint256 current, uint64 at);
    event WithdrawPolicySet(address indexed previous, address indexed current);
    /// @dev Nome e assinatura definidos pelo ERC-7572.
    event ContractURIUpdated();
    /// @dev O v2 mudava as travas em silêncio. Sem este evento, desligar o teto de variação
    ///      para um reporte extraordinário não deixa rastro nenhum on-chain.
    event ReportGuardsSet(uint64 maxReportAge, uint16 maxReportDeviationBps, address indexed by);
    event DustSwept(address indexed to, uint256 amount, uint256 clearedDeployedCapital);

    error ReportStale(uint64 reportedAt, uint64 maxAge);
    error ReportDeviationTooHigh(uint256 previous, uint256 requested, uint16 maxBps);
    error InsufficientIdleBalance(uint256 requested, uint256 idle);
    error FirstDepositTooSmall(uint256 assets, uint256 minimum);
    error NoDeployedCapital();
    error ZeroAddress();
    /// @dev Varredura com cota emitida seria o admin tirando o dinheiro dos cotistas.
    error SharesOutstanding(uint256 totalSupply);
    error NothingToSweep();

    /// @notice Parâmetros de construção, agrupados num struct por necessidade e por clareza:
    ///         doze parâmetros soltos estouram a pilha do solc sem `viaIR`, e um struct
    ///         nomeado no ponto de chamada elimina a chance de trocar dois endereços de
    ///         posição — o tipo de erro que só aparece quando o papel errado tenta agir.
    struct VaultConfig {
        IERC20 asset; // stablecoin de lastro. IMUTÁVEL — outro lastro exige outro vault
        string name;
        string symbol;
        address admin; // concede papéis, pluga compliance e política. Não move dinheiro
        address manager; // saca e devolve capital (idealmente multisig/timelock)
        address oracle; // reporta o valor do capital aplicado
        address enforcer; // congela cota e faz transferência forçada (ordem judicial)
        address complianceModule; // módulo uRWA, ou address(0) para fundo livre
        uint64 maxReportAge;
        uint16 maxReportDeviationBps;
        uint256 minFirstDeposit;
        string contractURI;
    }

    constructor(VaultConfig memory c)
        ERC20(c.name, c.symbol)
        ERC4626(c.asset)
        // ISSUER_ROLE vai para address(0) DE PROPÓSITO: um vault não tem emissão. A cota
        // nasce de depósito e morre em resgate, então não existe caminho de mint/burn
        // discricionário para alguém exercer. Conceder o papel a um endereço real seria
        // dar um poder que não existe.
        CompliantToken(c.admin, address(0), c.enforcer, c.complianceModule)
    {
        if (c.admin == address(0) || c.manager == address(0) || c.oracle == address(0)) revert ZeroAddress();
        if (c.enforcer == address(0)) revert ZeroAddress();
        if (address(c.asset) == address(0)) revert ZeroAddress();

        maxReportAge = c.maxReportAge;
        maxReportDeviationBps = c.maxReportDeviationBps;
        minFirstDeposit = c.minFirstDeposit;
        _contractURI = c.contractURI;

        _grantRole(MANAGER_ROLE, c.manager);
        _grantRole(ORACLE_ROLE, c.oracle);
    }

    // ────────────────────────────── Metadado (ERC-7572) ──────────────────────────────

    /// @notice Metadado do fundo: gestor, regulamento, política de investimento.
    /// @dev Aditivo ao ERC-4626, que é uma interface MÍNIMA — quem chama `deposit`,
    ///      `convertToAssets` ou `maxRedeem` não é afetado. ERC-7572 é o padrão canônico
    ///      para isso, então é padrão sobre padrão, não desvio.
    function contractURI() external view returns (string memory) {
        return _contractURI;
    }

    function setContractURI(string calldata uri) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _contractURI = uri;
        emit ContractURIUpdated();
    }

    // ────────────────────────────── Contabilidade ──────────────────────────────

    /// @notice Saldo ocioso + capital aplicado. A primeira parcela é verificável on-chain;
    ///         a segunda é o valor reportado pelo ORACLE.
    /// @dev NÃO desconta `unbookedAssets()`, de propósito. Descontar tornaria a doação inócua
    ///      em vez de apenas encarecida, mas prenderia dinheiro enviado por engano até um
    ///      sweep — que exige supply zero. Sair disso pediria um poder de admin novo sobre o
    ///      preço da cota, então o contador existe para MEDIR antes de alguém decidir.
    function totalAssets() public view override returns (uint256) {
        return IERC20(asset()).balanceOf(address(this)) + deployedCapital;
    }

    /// @notice Parcela verificável de `totalAssets()` — o que está de fato no contrato.
    function idleAssets() public view returns (uint256) {
        return IERC20(asset()).balanceOf(address(this));
    }

    /// @notice Lastro no contrato que NÃO entrou por depósito nem por `returnCapital`.
    ///
    ///         Diferente de zero significa que alguém transferiu a stablecoin direto para o
    ///         contrato. O caso que motivou isto: capital devolvido por transferência ERC-20
    ///         em vez de `returnCapital`, o que deixa `deployedCapital` intacto e faz
    ///         `totalAssets()` contar o mesmo dinheiro duas vezes — o preço da cota dobra sem
    ///         nada ter rendido. Aqui a divergência fica legível on-chain.
    ///
    ///         O remédio é reportar o capital que de fato continua aplicado (zero, se tudo
    ///         voltou), NÃO sacar de novo — sacar reabriria a posição.
    /// @dev Saturado em zero: um lastro com taxa na transferência faria o contabilizado passar
    ///      o saldo real, e um valor negativo aqui não descreve nada.
    function unbookedAssets() public view returns (uint256) {
        uint256 bal = idleAssets();
        return bal > _idleBooked ? bal - _idleBooked : 0;
    }

    // ────────────────────────────── Gestor: saque e devolução ──────────────────────────────

    /// @notice Saca capital para aplicar em ativo real. NEUTRO no preço da cota: o valor
    ///         apenas migra de `idleAssets` para `deployedCapital`, e `totalAssets` não muda.
    /// @dev A política é consultada ANTES de mexer em estado e antes da transferência —
    ///      checks-then-effects — e a função é `nonReentrant` porque essa chamada sai para um
    ///      contrato arbitrário escolhido pelo admin.
    function withdrawCapital(address to, uint256 amount) external onlyRole(MANAGER_ROLE) nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        uint256 idle = idleAssets();
        if (amount > idle) revert InsufficientIdleBalance(amount, idle);

        IWithdrawPolicy policy = withdrawPolicy;
        if (address(policy) != address(0)) {
            policy.enforceWithdraw(address(this), msg.sender, to, amount);
        }

        deployedCapital += amount;
        reportedAt = uint64(block.timestamp); // o saque é, ele mesmo, informação fresca
        _idleBooked = amount >= _idleBooked ? 0 : _idleBooked - amount;
        IERC20(asset()).safeTransfer(to, amount);

        emit CapitalWithdrawn(to, amount, deployedCapital);
    }

    /// @notice Devolve capital ao vault. O gestor precisa ter dado `approve` antes.
    ///         Também neutro no preço: baixa `deployedCapital` no que voltou. Se voltar MAIS
    ///         que o aplicado (juros), o excedente fica como saldo e o preço da cota sobe —
    ///         que é exatamente o rendimento chegando.
    function returnCapital(uint256 amount) external onlyRole(MANAGER_ROLE) {
        IERC20(asset()).safeTransferFrom(msg.sender, address(this), amount);

        uint256 previous = deployedCapital;
        deployedCapital = amount >= previous ? 0 : previous - amount;
        reportedAt = uint64(block.timestamp);
        _idleBooked += amount;

        emit CapitalReturned(msg.sender, amount, deployedCapital);
    }

    // ────────────────────────────── Oráculo: marcação ──────────────────────────────

    /// @notice Reporta o valor atual do capital aplicado. É a ÚNICA função que move o preço
    ///         da cota — daí o teto de variação. A base de comparação do primeiro reporte é
    ///         o valor efetivamente sacado, então todo reporte é limitado.
    function reportDeployedCapital(uint256 amount) external onlyRole(ORACLE_ROLE) {
        uint256 previous = deployedCapital;

        // Sem capital fora do contrato não existe posição para marcar, e marcar o que não
        // saiu CRIA valor do nada: `totalAssets` sobe sem lastro nenhum e o preço da cota
        // com ele. Só `withdrawCapital` abre posição, a partir de uma transferência real.
        if (previous == 0) revert NoDeployedCapital();

        if (maxReportDeviationBps != 0) {
            uint256 diff = amount > previous ? amount - previous : previous - amount;
            if (diff * 10_000 > previous * maxReportDeviationBps) {
                revert ReportDeviationTooHigh(previous, amount, maxReportDeviationBps);
            }
        }

        deployedCapital = amount;
        reportedAt = uint64(block.timestamp);

        emit DeployedCapitalReported(previous, amount, reportedAt);
    }

    // ────────────────────────────── Admin ──────────────────────────────

    /// @notice Instala (ou remove, com `address(0)`) a política de destino do saque.
    function setWithdrawPolicy(IWithdrawPolicy policy) external onlyRole(DEFAULT_ADMIN_ROLE) {
        address previous = address(withdrawPolicy);
        withdrawPolicy = policy;
        emit WithdrawPolicySet(previous, address(policy));
    }

    /// @notice Ajusta a trava de validade e o teto de variação do reporte.
    /// @dev Emite evento nas duas pontas porque desligar o teto não deixava rastro: um auditor
    ///      lia um reporte de 52 → 0 que o teto de 10% deveria ter recusado, sem nada
    ///      explicando como passou. O reporte extraordinário da plataforma faz exatamente
    ///      isso — desliga, reporta, religa.
    function setReportGuards(uint64 maxReportAge_, uint16 maxReportDeviationBps_)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        maxReportAge = maxReportAge_;
        maxReportDeviationBps = maxReportDeviationBps_;
        emit ReportGuardsSet(maxReportAge_, maxReportDeviationBps_, msg.sender);
    }

    /// @notice Varre o que sobrou num fundo SEM NENHUMA COTA emitida, para a próxima cota
    ///         nascer a exatamente uma unidade do lastro. Zera também um `deployedCapital`
    ///         residual, que sem cotista é marcação de uma posição que não pertence a ninguém.
    /// @dev O guard em `totalSupply() == 0` é a operação inteira. Com uma única cota emitida,
    ///      isto seria o admin sacando o dinheiro do cotista e dando baixa na marcação dele —
    ///      e é por isso que a checagem não tem exceção, tolerância nem parâmetro.
    ///
    ///      `nonReentrant` porque `to` é escolhido por quem chama e pode ser um contrato.
    ///
    ///      A alternativa — o ÚLTIMO resgate pagar `totalAssets` integral — foi descartada, e
    ///      não reabra: exigiria a mesma condição especial em `previewRedeem`,
    ///      `previewWithdraw`, `maxWithdraw` e `maxRedeem`, porque o EIP proíbe
    ///      `previewRedeem` prometer menos do que `redeem` paga. Quatro funções do padrão com
    ///      um caso de borda é muito mais superfície de auditoria que uma função isolada.
    /// @param to Destino da poeira. Explícito no calldata e no evento, para o movimento ser
    ///           auditável sem depender de quem assinou.
    /// @return swept Quanto de lastro saiu do contrato.
    function sweepDust(address to)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
        nonReentrant
        returns (uint256 swept)
    {
        if (to == address(0)) revert ZeroAddress();
        uint256 supply = totalSupply();
        if (supply != 0) revert SharesOutstanding(supply);

        swept = idleAssets();
        uint256 cleared = deployedCapital;
        if (swept == 0 && cleared == 0) revert NothingToSweep();

        if (cleared != 0) {
            deployedCapital = 0;
            reportedAt = uint64(block.timestamp);
            emit DeployedCapitalReported(cleared, 0, reportedAt);
        }
        if (swept != 0) {
            // Tudo saiu, então nada mais está contabilizado como ocioso.
            _idleBooked = 0;
            IERC20(asset()).safeTransfer(to, swept);
        }

        emit DustSwept(to, swept, cleared);
    }

    // ────────────────────────────── Freeze / enforcement ──────────────────────────────

    /// @notice Cota transferível = saldo - congelado (saturado em 0).
    function availableBalance(address account) public view returns (uint256) {
        uint256 bal = balanceOf(account);
        uint256 f = _frozen[account][FUNGIBLE_ID];
        return f >= bal ? 0 : bal - f;
    }

    /// @notice Transferência forçada de cota (ordem judicial/recuperação). Ignora allowlist
    ///         da origem e o freeze, mas valida o destino.
    function forcedTransfer(address from, address to, uint256 amount)
        external
        onlyRole(ENFORCER_ROLE)
        returns (bool)
    {
        if (!canReceive(to)) revert CannotReceive(to);

        _enforcing = true;
        _transfer(from, to, amount);
        _enforcing = false;

        uint256 bal = balanceOf(from);
        if (_frozen[from][FUNGIBLE_ID] > bal) {
            _frozen[from][FUNGIBLE_ID] = bal;
            emit Frozen(from, FUNGIBLE_ID, bal);
        }

        emit ForcedTransfer(from, to, FUNGIBLE_ID, amount);
        return true;
    }

    /// @notice Consulta advisory usada pela API antes de submeter. O guard real é o `_update`.
    function canTransfer(address from, address to, uint256 amount) external view returns (bool) {
        if (paused()) return false;
        if (from != address(0) && availableBalance(from) < amount) return false;
        return _complianceAllows(from, to, FUNGIBLE_ID, amount);
    }

    // ────────────────────────── Limites: o ERC-4626 exige honestidade ──────────────────────────

    /// @dev A spec do ERC-4626 diz que `max*` devolve o que NÃO reverteria. Com portão, pause
    ///      e freeze isso deixa de ser trivial, e um `max*` que mente transforma uma recusa
    ///      clara em revert opaco — que é a classe de bug mais caro de diagnosticar.

    function maxDeposit(address receiver) public view override returns (uint256) {
        if (paused() || !canReceive(receiver)) return 0;
        return super.maxDeposit(receiver);
    }

    function maxMint(address receiver) public view override returns (uint256) {
        if (paused() || !canReceive(receiver)) return 0;
        return super.maxMint(receiver);
    }

    /// @dev Resgate só acontece contra saldo ocioso — o que está no recebível não volta na
    ///      hora — e só sobre cota não congelada.
    function maxWithdraw(address owner) public view override returns (uint256) {
        if (paused()) return 0;
        uint256 byShares = _convertToAssets(availableBalance(owner), Math.Rounding.Floor);
        return Math.min(byShares, idleAssets());
    }

    function maxRedeem(address owner) public view override returns (uint256) {
        if (paused()) return 0;
        uint256 byLiquidity = _convertToShares(idleAssets(), Math.Rounding.Floor);
        return Math.min(availableBalance(owner), byLiquidity);
    }

    // ────────────────────────────── Ganchos ──────────────────────────────

    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal override {
        if (totalSupply() == 0 && assets < minFirstDeposit) {
            revert FirstDepositTooSmall(assets, minFirstDeposit);
        }
        _requireFreshReport();
        super._deposit(caller, receiver, assets, shares);
        _idleBooked += assets;
    }

    function _withdraw(address caller, address receiver, address owner, uint256 assets, uint256 shares)
        internal
        override
    {
        _requireFreshReport();
        super._withdraw(caller, receiver, owner, assets, shares);
        _idleBooked = assets >= _idleBooked ? 0 : _idleBooked - assets;
    }

    /// @dev Gancho central: TODO movimento de cota passa aqui — transferência, o mint do
    ///      depósito (`from == 0`) e o burn do resgate (`to == 0`). É o que faz um único
    ///      ponto de decisão cobrir os três.
    function _update(address from, address to, uint256 value) internal override {
        if (!_enforcing) {
            if (paused()) revert EnforcedPause();

            // Saída (transferência ou resgate) respeita o congelado.
            if (from != address(0)) {
                uint256 avail = availableBalance(from);
                if (avail < value) {
                    revert InsufficientUnfrozenBalance(from, FUNGIBLE_ID, value, avail);
                }
            }

            // Compliance. O módulo libera `to == address(0)`, então o RESGATE nunca é barrado
            // pelo portão: um fundo que impede o investidor de sair do próprio dinheiro é uma
            // armadilha, não um controle.
            if (!_complianceAllows(from, to, FUNGIBLE_ID, value)) {
                revert CannotTransfer(from, to, FUNGIBLE_ID, value);
            }
        }

        super._update(from, to, value);
    }

    /// @dev Com capital aplicado, o preço da cota depende de um número reportado. Se esse
    ///      número está velho, entrar ou sair executa a preço defasado — e isso transfere
    ///      valor entre investidores. Sem capital fora, não há marcação e a trava não se aplica.
    function _requireFreshReport() internal view {
        if (deployedCapital == 0 || maxReportAge == 0) return;
        if (block.timestamp > uint256(reportedAt) + uint256(maxReportAge)) {
            revert ReportStale(reportedAt, maxReportAge);
        }
    }
}

