// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ICompliance} from "../interfaces/ICompliance.sol";

/// @title CompliantToken — base uRWA compartilhada por ERC-20/721/1155
/// @notice Concentra o que é comum aos três padrões da família: papéis (issuer/enforcer/
///         pauser/admin), o módulo de compliance PLUGÁVEL e OPCIONAL, o congelamento por
///         (conta, tokenId) e o pause. O gancho de transferência (_update) mora em cada
///         token porque a assinatura difere por padrão — aqui ficam só os helpers.
/// @dev    `compliance == address(0)` significa SEM portão: o token se comporta como um
///         token comum (livre). Plugar/trocar/despugar é operação de admin (setCompliance).
///         Convenção de tokenId: ERC-20 usa 0 (fungível), ERC-721 o id do NFT, ERC-1155 a
///         tranche. `_enforcing` sinaliza uma operação de ENFORCER (forcedTransfer), que
///         pula compliance/freeze/pause no _update.
abstract contract CompliantToken is AccessControl, Pausable {
    bytes32 public constant ISSUER_ROLE = keccak256("ISSUER_ROLE"); // mint / burn / supply
    bytes32 public constant ENFORCER_ROLE = keccak256("ENFORCER_ROLE"); // freeze / forcedTransfer
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE"); // pause / unpause

    /// @notice Módulo de compliance (allowlist/KYC). address(0) = sem portão.
    ICompliance public compliance;

    /// @notice Quantidade congelada por (conta, tokenId). Pode exceder o saldo (permitido).
    mapping(address => mapping(uint256 => uint256)) internal _frozen;

    /// @dev Quando true, o _update do token pula compliance/freeze/pause (só forcedTransfer).
    bool internal _enforcing;

    event ComplianceUpdated(address indexed module);
    event Frozen(address indexed account, uint256 indexed tokenId, uint256 amount);
    event ForcedTransfer(address indexed from, address indexed to, uint256 indexed tokenId, uint256 amount);

    error CannotReceive(address account);
    error CannotTransfer(address from, address to, uint256 tokenId, uint256 amount);
    error InsufficientUnfrozenBalance(address account, uint256 tokenId, uint256 amount, uint256 unfrozen);

    constructor(address admin, address issuer, address enforcer, address complianceModule) {
        // complianceModule pode ser address(0) — token livre (sem portão).
        compliance = ICompliance(complianceModule);

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ISSUER_ROLE, issuer);
        _grantRole(ENFORCER_ROLE, enforcer);
        _grantRole(PAUSER_ROLE, admin);
    }

    // ────────────────────────────── Admin: plugar/despugar módulo ──────────────────────────────

    /// @notice Troca (ou remove, com address(0)) o módulo de compliance. Admin-only.
    function setCompliance(address module) external onlyRole(DEFAULT_ADMIN_ROLE) {
        compliance = ICompliance(module);
        emit ComplianceUpdated(module);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // ────────────────────────────── Freeze (ENFORCER) ──────────────────────────────

    function getFrozenTokens(address account, uint256 tokenId) public view returns (uint256) {
        return _frozen[account][tokenId];
    }

    function setFrozenTokens(address account, uint256 tokenId, uint256 amount)
        external
        onlyRole(ENFORCER_ROLE)
        returns (bool)
    {
        _frozen[account][tokenId] = amount;
        emit Frozen(account, tokenId, amount);
        return true;
    }

    // ────────────────────────────── Consultas de compliance ──────────────────────────────

    /// @notice Elegibilidade de origem. Sem módulo plugado → sempre true.
    function canSend(address account) public view returns (bool) {
        return address(compliance) == address(0) || compliance.canSend(account);
    }

